{
  "summary": "Changes Tor control authentication to send the -torpassword argument hex-encoded instead of as a quoted string. Also adds a functional test covering authentication with passwords containing backslashes and quotation marks.",
  "problem": "Users configuring a Tor control password containing backslashes experience authentication failures because Bitcoin Core only escapes double quotes in quoted strings, causing Tor to misinterpret backslash escape sequences or leave the string unterminated.",
  "evidence": [
    "PR description: 'The Tor password was sent as a QuotedString with only double quotes escaped; as Tor interprets backslash escapes inside it, any password containing a backslash was mangled (or left the string unterminated).'",
    "PR description: 'The Tor Control spec deliberately allows the token to be sent as unquoted hex \"to avoid escaping issues\", as the SAFECOOKIE response already is.'"
  ],
  "dependencies": {
    "depends_on": [],
    "enables": []
  },
  "scope_notes": "Alternative approach to open PR #36374, which attempts to solve the same bug by escaping backslashes rather than using hex encoding.",
  "changed_since_previous": "",
  "card": "Encodes -torpassword as unquoted hex when authenticating to Tor control rather than escaping quoted strings. Currently, passwords containing backslash characters are mangled by Tor's escape parsing and fail authentication. The Tor Control specification specifically permits hex encoding to bypass string-escaping issues.",
  "needs": [
    "diff"
  ],
  "confidence": "medium",
  "uncertainties": [
    "The patch diff was omitted, though the commit message and PR description detail the hex-encoding change and functional test addition."
  ],
  "risk": {
    "level": "low",
    "touches": [
      "other",
      "tests"
    ],
    "why": "A mistake in encoding the password could cause Tor control authentication to fail for nodes using -torpassword, preventing automatic hidden service creation."
  }
}
